import { useState } from "react";

// Rendered inside <ErrorBoundary fallback={<CheckoutError />}>
export function PayButton({ orderId }: { orderId: string }) {
  const [paying, setPaying] = useState(false);

  async function handleClick() {
    setPaying(true);
    await chargeCard(orderId); // if this rejects, no boundary sees it
    setPaying(false); // never runs: stuck on "Paying…"
  }

  return (
    <button onClick={handleClick} disabled={paying}>
      {paying ? "Paying…" : "Pay"}
    </button>
  );
}

import { useTransition } from "react";

// Rendered inside <ErrorBoundary fallback={<CheckoutError />}>
export function PayButton({ orderId }: { orderId: string }) {
  const [isPending, startTransition] = useTransition();

  function handleClick() {
    startTransition(async () => {
      await chargeCard(orderId); // a rejection shows the fallback
    });
  }

  return (
    <button onClick={handleClick} disabled={isPending}>
      {isPending ? "Paying…" : "Pay"}
    </button>
  );
}
